export function createBootstrapServices(deps) {
  const {
    createRuntimeBoundaryBridge,
    createBpmEngine,
    createSerialOutput,
    createOutputPipeline,
    createUiSync,
    createUiStateSync,
    createUiBindings,
    createUiPickers,
    SHELL_VIEW_ONLY,
    state,
    settings,
    transitionSettings,
    modules,
    lists,
    controls,
    sliders,
    fxControls,
    layerButtons,
    storageKey,
    settingsKey,
    transitionKey,
    mappingKey,
    serialKey,
    blendModes,
    defaultParamLabels,
    blendGroups,
    option,
    blendModeLabel,
    setSelectValue,
    clamp,
    clamp01,
    clampInt,
    bpmValue,
    beatStartedAtValue,
    clampResetId,
    gammaValue,
    contrastValue,
    transitionSecondsValue,
    normalizeManualPalette,
    normalizeManualPaletteActive,
    drawManualPaletteWheel,
    cleanModuleName,
    byIdRef,
    documentRef,
    refreshRangeVisuals,
    syncFullscreenButtonLabel,
    syncPreviewModeControls,
    syncMasterValue,
    syncCrossMouseControl,
    applyCrossfaderPlacement,
    commitState,
    tapBpm,
    syncControls,
    randomizeSingleFile,
    resetBeat,
    setMasterFlash,
    numberValue,
    applyRangeVisual,
    stepFile,
    randomizeLayerParams,
    bindCheckbox,
    colorFromWheelEvent,
    cloneLayerState,
    startLayerTransition,
    captureLayerModules,
    getPreviewMode,
    setPreviewMode,
    cyclePixelPreviewMode,
    cycleShaderPreviewMode,
    getBeatPosition,
    normalizedParams,
    normalizeValue,
    renderShaderLayerCanvas,
    loadModule,
    switchLayerModule,
    isSerialPipelineEnabled,
    schedulerDebugState,
    getOutputMode,
    getSerialSettings,
    getSocket,
    getLastBeatResetId,
    setLastBeatResetId,
    setViewportSize,
    setSerialReversedRows,
    setSerialEnabledRows,
    setSerialBrightnessRows,
    setSerialPixelLimitRows,
    setSerialOutputRouteRows,
    setSerialColorOrderRows,
    onViewportChanged,
    setSerialSettings,
    setLayerPreviewDisabled,
    getBeatStartedAt,
    setBeatStartedAt,
    getLastTap,
    setLastTap,
    getWidth,
    getHeight,
    getSerialReversedRows,
    getSerialEnabledRows,
    getSerialBrightnessRows,
    getSerialPixelLimitRows,
    getSerialOutputRouteRows,
    getSerialColorOrderRows,
    getBlxNetConfig,
    getBlxSerialBaud,
    getSerialFrameBusy,
    setSerialFrameBusy,
    getLastSerialFrameAt,
    getSerialPauseUntil,
    setSerialPauseUntil,
    getSerialConflictCount,
    setSerialConflictCount,
    setLastSerialFrameAt,
    onOutputPipelineMetrics,
    getGpuReady,
    getLastPreviewRenderer,
    manualPaletteCollapsed,
    thumbCache,
    runtimeProfile
  } = deps;

  function isSerialRoutePreferred() {
    const mode = String(getOutputMode?.() || settings?.outputMode || "preview").toLowerCase();
    const serial = getSerialSettings?.() || {};
    const serialRouteActive = serial.enabled === true
      || settings?.routerSerialEnabled === true
      || ["serial", "blx_serial", "blx_net"].includes(mode);
    const explicitNetworkMode = ["artnet", "sacn", "wifi", "espnow"].includes(mode);
    return serialRouteActive && !explicitNetworkMode;
  }

  function getUnifiedTargetFps() {
    const serial = getSerialSettings?.() || {};
    if (isSerialRoutePreferred()) {
      return Math.max(1, Number(serial.fps || settings?.serialFps || settings?.fps || 60));
    }
    return Math.max(1, Number(settings?.fps || 60));
  }

  function getUnifiedSerialSettings() {
    const serial = getSerialSettings?.() || {};
    const targetFps = getUnifiedTargetFps();

    // STEP22NR: do not apply the old serial safety FPS cap to ArtNet/network
    // output. This helper is still named "SerialSettings" because legacy code
    // uses it for every output route, including sendArtnetLiveFrame(). The old
    // fallback `Math.min(targetFps, 25)` silently forced ArtNet to ~20–26 FPS
    // even while the output clock and debug target said 60 FPS. Keep the cap
    // only for the real serial/BLX-serial route; network routes must inherit
    // the unified output target FPS.
    if (!isSerialRoutePreferred()) {
      return {
        ...serial,
        fps: targetFps,
        networkOutputFpsSource: "unified-output-target-step22nr"
      };
    }

    const serialFps = Math.max(1, Number(serial.fps || targetFps));
    return {
      ...serial,
      fps: Math.min(targetFps, serialFps)
    };
  }

  const runtimeBoundaryBridge = createRuntimeBoundaryBridge({
    state,
    settings,
    transitionSettings,
    storageKey,
    settingsKey,
    transitionKey,
    mappingKey,
    serialKey,
    blendModes,
    clamp01,
    clampInt,
    bpmValue,
    beatStartedAtValue,
    clampResetId,
    gammaValue,
    contrastValue,
    transitionSecondsValue,
    normalizeManualPalette,
    normalizeManualPaletteActive,
    getLastBeatResetId,
    setLastBeatResetId,
    setViewportSize,
    setSerialReversedRows,
    setSerialEnabledRows,
    setSerialBrightnessRows,
    setSerialPixelLimitRows,
    setSerialOutputRouteRows,
    setSerialColorOrderRows,
    onViewportChanged,
    getSerialSettings,
    setSerialSettings,
    setLayerPreviewDisabled
  });
  const stateBridge = runtimeBoundaryBridge.stateBridge;

  const bpmEngine = createBpmEngine({
    state,
    getBeatStartedAt,
    setBeatStartedAt,
    getLastBeatResetId,
    setLastBeatResetId,
    getLastTap,
    setLastTap,
    syncControls,
    commitState
  });

  const serialOutput = SHELL_VIEW_ONLY ? null : createSerialOutput({
    getWidth,
    getHeight,
    getSerialReversedRows,
    getSerialEnabledRows,
    getSerialBrightnessRows,
    getSerialPixelLimitRows,
    getSerialOutputRouteRows,
    getSerialColorOrderRows,
    clamp,
    getOutputMode,
    getBlxNetConfig,
    getBlxSerialBaud,
    getSerialSettings: getUnifiedSerialSettings,
    getSerialFrameBusy,
    setSerialFrameBusy,
    getLastSerialFrameAt,
    getSerialPauseUntil,
    setSerialPauseUntil,
    getSerialConflictCount,
    setSerialConflictCount,
    getSocket,
    setLastSerialFrameAt
  });

  const outputPipeline = SHELL_VIEW_ONLY ? null : createOutputPipeline({
    getNow: () => performance.now(),
    isEnabled: isSerialPipelineEnabled,
    getTargetFps: getUnifiedTargetFps,
    getPauseUntil: getSerialPauseUntil,
    setPauseUntil: setSerialPauseUntil,
    transport: createOutputTransportAdapter({
      name: "serial",
      sendFrame: (frame) => serialOutput?.sendSerialFrame(frame)
    }),
    onMetrics: onOutputPipelineMetrics
  });

  const uiSync = createUiSync({
    controls,
    state,
    settings,
    modules,
    layerButtons,
    transitionSettings,
    defaultParamLabels,
    blendGroups,
    blendModes,
    option,
    blendModeLabel,
    setSelectValue,
    clampInt,
    normalizeManualPalette,
    normalizeManualPaletteActive,
    drawManualPaletteWheel
  });

  const uiStateSync = createUiStateSync({
    controls,
    state,
    settings,
    modules,
    layerButtons,
    sliders,
    fxControls,
    transitionSettings,
    getSerialSettings,
    defaultParamLabels,
    uiSync,
    blendModeLabel,
    setSelectValue,
    clampInt,
    normalizeManualPalette,
    normalizeManualPaletteActive,
    drawManualPaletteWheel,
    cleanModuleName,
    byIdRef,
    documentRef,
    manualPaletteCollapsed,
    refreshRangeVisuals,
    syncFullscreenButtonLabel,
    syncPreviewModeControls,
    syncMasterValue,
    syncCrossMouseControl,
    getGpuReady,
    getLastPreviewRenderer,
    applyCrossfaderPlacement
  });

  const uiBindings = createUiBindings({
    controls,
    state,
    tapBpm,
    syncControls,
    commitState,
    randomizeSingleFile,
    resetBeat,
    setMasterFlash,
    numberValue,
    applyRangeVisual,
    stepFile,
    byId: byIdRef,
    randomizeLayerParams,
    bindCheckbox,
    layerButtons,
    normalizeManualPaletteActive,
    colorFromWheelEvent,
    cloneLayerState,
    startLayerTransition,
    captureLayerModules,
    getPreviewMode,
    setPreviewMode,
    cyclePixelPreviewMode,
    cycleShaderPreviewMode
  });

  const uiPickers = createUiPickers({
    state,
    modules,
    lists,
    thumbCache,
    normalizedParams,
    getBeatPosition,
    normalizeValue,
    clamp,
    renderShaderLayerCanvas,
    cleanModuleName,
    loadModule,
    switchLayerModule,
    documentRef,
    runtimeProfile
  });

  return {
    stateBridge,
    bpmEngine,
    serialOutput,
    outputPipeline,
    uiSync,
    uiStateSync,
    uiBindings,
    uiPickers
  };
}
